18	
19	/** What a session's mode dictates, independent of engine: hooks, prompt, tool set, and the files a search may hand back. */
20	export type ModeSetup = { hooks?: SessionHooks; systemPrompt?: string; toolNames?: string[]; readable?: (relPath: string) => boolean }
21	
22	/** What the modes read from the workspace and its settings, and the maps a prompt carries, built when behind. */
23	export type ModeContext = {
24	  workspaceRoot: string
25	  verifyRules(): VerifyRule[]
26	  /** Docs the blind planner must not see, so neither the map nor the evaluation may describe them. */
27	  planIgnore(): string[]
28	  cleanupLimits(): Limits
29	  withMap(record: SessionRecord, systemPrompt: string): Promise<string>
30	  withDocs(record: SessionRecord, systemPrompt: string): Promise<string>
31	  /** The project's and the person's memory index, for every mode but the blind planner. */
32	  withMemories(record: SessionRecord, systemPrompt: string): Promise<string>
33	}
34	
35	export async function modeSetup(record: SessionRecord, ctx: ModeContext): Promise<ModeSetup> {
36	  const { workspaceRoot } = ctx
37	  // A chat may write a spec when asked to, held to the contract like the planner's.
38	  const chat = { hooks: new SpecContract(workspaceRoot) }
39	  if (record.access === 'full') return chat
40	  switch (record.mode) {
41	    case 'chat':
42	      return chat
43	    case 'implement': {
44	      if (!record.feature) throw new Error('An implement session needs a feature name')
45	      return {
46	        // The user's answers amend the task's rules, held to the contract like the planner's writes.
47	        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
48	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules()))),
49	        toolNames: IMPLEMENT_TOOLS,
50	      }
51	    }
52	    case 'plan': {
53	      if (!record.feature) throw new Error('A plan session needs a feature name')
54	      const scope = blindPlanScope(record.feature, ctx.planIgnore())
55	      return {
56	        // The contract answers on the write that broke it, so the planner fixes the spec in the same turn.
57	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
58	        systemPrompt: await ctx.withDocs(record, blindPlanPrompt(record.feature, workspaceRoot)),
59	        toolNames: BLIND_PLAN_TOOLS,
60	        readable: readableIn(scope),
61	      }
62	    }
63	    case 'code-plan':
64	      // Read-only by its tool set: nothing to scope, and the build happens once the plan is approved.
65	      return {
66	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, await ctx.withDocs(record, codePlanPrompt(workspaceRoot)))),
67	        toolNames: CODE_PLAN_TOOLS,
68	      }
69	    case 'docs': {
70	      const scope = docsEvaluationScope(ctx.planIgnore())
71	      return {
72	        hooks: new ScopeGuard(workspaceRoot, scope),
73	        systemPrompt: await ctx.withMemories(record, await ctx.withDocs(record, docsEvaluationPrompt(workspaceRoot))),
74	        toolNames: DOCS_EVALUATION_TOOLS,
75	        readable: readableIn(scope),
76	      }
77	    }
78	    case 'file-decisions': {
79	      const scope = fileDecisionsScope(ctx.planIgnore())
80	      return {
81	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
82	        systemPrompt: await ctx.withMemories(record, await ctx.withDocs(record, fileDecisionsPrompt(workspaceRoot))),
83	        toolNames: FILE_DECISIONS_TOOLS,
84	        readable: readableIn(scope),
85	      }
86	    }
87	    case 'docs-map': {
88	      return {
89	        // The entry contract answers on the write that broke it, so a bad anchor never reaches a planner's prompt.
90	        hooks: composeHooks(new ScopeGuard(workspaceRoot, docsMapScope(record.files ?? [])), new DocsMapContract(workspaceRoot)),
91	        systemPrompt: await ctx.withMemories(record, docsMapPrompt(workspaceRoot)),
92	        toolNames: DOCS_MAP_TOOLS,
93	      }
94	    }
95	    case 'reconcile': {
96	      if (!record.feature) throw new Error('A reconcile session needs a feature name')
97	      return {
98	        hooks: composeHooks(
99	          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
100	          new SpecContract(workspaceRoot),
101	          new ScenarioContextContract(workspaceRoot, record.feature),
102	        ),
103	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot))),
104	        toolNames: RECONCILE_TOOLS,
105	      }
106	    }
107	    case 'cleanup': {
108	      if (!record.feature || !record.files) throw new Error('A cleanup session needs a feature name and the files to split')
109	      return {
110	        hooks: new ScopeGuard(workspaceRoot, cleanupScope(record.files)),
111	        systemPrompt: await ctx.withMemories(record, cleanupPrompt(record.feature, workspaceRoot, ctx.cleanupLimits())),
112	        toolNames: CLEANUP_TOOLS,
113	      }
114	    }
115	  }
116	}
